  ('lamuahaatscha', 'Lamuahaatscha', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Lamurhatscher', '[{"kategorie": "wörtlich", "text": "\"L''amour-Hatscher\" (Determinativkompositum aus \"l''amour\"=\"Liebe\" und \"Hatscher\"=\"längerer, beschwerlicher Fußmarsch\" [vom arabischen \"Haddsch\"=\"islamischer Pilgermarsch nach Mekka\", der oft als sehr anstrengend und beschwerlich beschrieben wird])"}, {"kategorie": "scherzhaft für", "text": "\"langsamer Tanz\", \"Schmusetanz\" (romantisch langsames Musikstück, zu dem man eng umschlungen tanzt), \"Liebestänzchen\", \"Knutsch-Schlurfer\" , \"Gspusi-Schieber\" (=langsamer, enger Endlos-Tanz)"}]'::jsonb, ''),
